{
  "name": "get_fee_due",
  "description": "Return the pending fee amount in rupees for a student roll number. Use only when the user asks about fees.",
  "parameters": {
    "type": "object",
    "properties": {
      "roll_no": {"type": "string", "description": "Student roll number such as BCA2025-014"}
    },
    "required": ["roll_no"]
  }
}

import json

# 1. The real tool: ordinary Python
FEES = {"BCA2025-014": 12500, "BCA2025-021": 0}

def get_fee_due(roll_no):
    if roll_no not in FEES:
        return {"error": "Unknown roll number"}
    return {"roll_no": roll_no, "fee_due_rupees": FEES[roll_no]}

TOOLS = {"get_fee_due": get_fee_due}

# 2. Stand-in for the model: returns a tool request, then a final answer
def fake_model(messages):
    last = messages[-1]
    if last["role"] == "user":
        return {"tool": "get_fee_due", "args": {"roll_no": "BCA2025-014"}}
    data = json.loads(last["content"])
    return {"final": f"Pending fee is Rs {data['fee_due_rupees']}."}

# 3. The loop run by your program
messages = [{"role": "user", "content": "How much fee is due for BCA2025-014?"}]
for step in range(5):                      # hard limit on steps
    reply = fake_model(messages)
    if "final" in reply:
        print(reply["final"])
        break
    name, args = reply["tool"], reply["args"]
    if name not in TOOLS:                  # allow-list check
        raise ValueError("Tool not allowed")
    result = TOOLS[name](**args)
    messages.append({"role": "tool", "content": json.dumps(result)})

def route(category):
    handlers = {
        "Fees": "fees_prompt",
        "Exams": "exams_prompt",
        "Hostel": "hostel_prompt",
    }
    return handlers.get(category, "human_review")   # safe default

print(route("Fees"))      # fees_prompt
print(route("Parking"))   # human_review

state = {
    "goal": "Prepare weekly study plan",
    "done": ["read syllabus", "list weak topics"],
    "pending": ["schedule sessions", "add to calendar"],
    "facts": {"exam_date": "2025-05-10", "hours_per_day": 3},
}

def build_prompt(state):
    return (
        f"Goal: {state['goal']}\n"
        f"Completed: {', '.join(state['done'])}\n"
        f"Next steps: {', '.join(state['pending'])}\n"
        f"Known facts: {state['facts']}\n"
        "Do the first pending step only."
    )

print(build_prompt(state))

ALLOWED_RECIPIENTS = {"warden@college.example", "office@college.example"}

def send_email(to, body, approved=False):
    if to not in ALLOWED_RECIPIENTS:
        return {"error": "Recipient not allowed"}
    if not approved:
        return {"status": "needs_approval", "preview": body[:200]}
    return {"status": "sent"}   # real sending would happen here

print(send_email("stranger@mail.example", "Hello"))
print(send_email("office@college.example", "Fee query"))
